import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"kiwa v1.39 released — Security 深化 II (@kiwa-lab/security v0.2.0 advanced II 8 axis + 縦深化 pair 第 9 pair 2 段拡張)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.39/zenn-article.md","filePath":"announcements/v1.39/zenn-article.md"}'),s={name:"announcements/v1.39/zenn-article.md"};function n(o,e,c,l,d,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v1-39-released-—-security-深化-ii-kiwa-lab-security-v0-2-0-advanced-ii-8-axis-縦深化-pair-第-9-pair-2-段拡張" tabindex="-1">kiwa v1.39 released — Security 深化 II (@kiwa-lab/security v0.2.0 advanced II 8 axis + 縦深化 pair 第 9 pair 2 段拡張) <a class="header-anchor" href="#kiwa-v1-39-released-—-security-深化-ii-kiwa-lab-security-v0-2-0-advanced-ii-8-axis-縦深化-pair-第-9-pair-2-段拡張" aria-label="Permalink to &quot;kiwa v1.39 released — Security 深化 II (@kiwa-lab/security v0.2.0 advanced II 8 axis + 縦深化 pair 第 9 pair 2 段拡張)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><strong>kiwa v1.39 released</strong> — Security 深化 II milestone</li><li><strong><code>@kiwa-lab/security</code> v0.1.0 → v0.2.0 minor bump</strong> — advanced II 8 axis + real driver env-gate + 4 provider × 8 axis neutral state machine</li><li><strong>8 axis advanced II semantics</strong> = mTLS + Zero-trust + SIEM + Incident response + Cryptography advanced + Container/K8s + Supply chain + Web Vitals security</li><li><strong>3 dogfood app 新規</strong> — security-mtls-zero-trust-app (74 test) + security-siem-incident-app (85 test) + security-supply-chain-slsa-app (76 test)</li><li><strong>縦深化 pair pattern 第 9 pair 2 段拡張</strong> — Security v1.37 (v0.1 base) → v1.39 (v0.2 advanced II) の 2 段拡張、 11 pair 連続化</li><li><strong>17 milestone 連続 snippet validation streak</strong> (v1.23-v1.39)</li><li><strong>kiwa 系 monorepo 36 packages 維持</strong> (security 既存 package の minor 拡張)</li><li>v1.11 以降 29 milestone 連続完遂</li></ul><h2 id="v1-39-が解決したい問題-—-security-advanced-ii-production-semantics-の-testing-gap" tabindex="-1">v1.39 が解決したい問題 — Security advanced II production semantics の testing gap <a class="header-anchor" href="#v1-39-が解決したい問題-—-security-advanced-ii-production-semantics-の-testing-gap" aria-label="Permalink to &quot;v1.39 が解決したい問題 — Security advanced II production semantics の testing gap&quot;">​</a></h2><p>kiwa は v1.37 まで dApp / web app / full-stack framework / 実 backend / real-time / payment / observability / search / AI-LLM / security base の 36 layer + release-invariants + a11y + component / performance / mutation の quality gate maximum grid を cover していたが、 Security 領域は v1.37 で 4 provider (helmet + express-rate-limit + casbin + coraza) の base 8 axis (CSP + Rate limit + Authorization + WAF + Threat model + Secrets scanning + SBOM + Security headers) 統一 mock を land した base layer に留まり、 production の advanced II semantics (mTLS + certificate pinning / Zero-trust device posture / SIEM audit log tamper-evident / Incident response playbook / Cryptography AEAD + post-quantum / Container / Kubernetes admission controller / Supply chain SLSA + provenance / Web Vitals SRI + trusted types) が <strong>未 cover</strong> の状態だった.</p><p>v1.39 で <code>@kiwa-lab/security</code> v0.1.0 → v0.2.0 minor bump し、 advanced II 8 axis を istio + opa + siem-splunk + vault の 4 provider 統一 mock として実装、 mTLS handshake + SPKI pinning + OCSP stapling、 Zero-trust device posture + risk score + JIT、 SIEM tamper-evident seal + correlation、 Incident response playbook + severity + forensics、 Cryptography AEAD + KDF + envelope + post-quantum ML-KEM、 Container / Kubernetes pod security + admission controller、 Supply chain SLSA + Sigstore + in-toto、 Web Vitals SRI + trusted types + COOP/COEP を 1 test surface で扱える Security advanced II backbone testing 基盤を追加した.</p><h2 id="v1-39-で追加した-8-axis-advanced-ii-security-semantics" tabindex="-1">v1.39 で追加した 8 axis advanced II security semantics <a class="header-anchor" href="#v1-39-で追加した-8-axis-advanced-ii-security-semantics" aria-label="Permalink to &quot;v1.39 で追加した 8 axis advanced II security semantics&quot;">​</a></h2><h3 id="_1-mtls-certificate-pinning" tabindex="-1">1. mTLS + certificate pinning <a class="header-anchor" href="#_1-mtls-certificate-pinning" aria-label="Permalink to &quot;1. mTLS + certificate pinning&quot;">​</a></h3><p>mTLS handshake + SPKI pinning + OCSP stapling + CT (Certificate Transparency) log + certificate rotation + certificate revocation + client cert authentication.</p><h3 id="_2-zero-trust-architecture" tabindex="-1">2. Zero-trust architecture <a class="header-anchor" href="#_2-zero-trust-architecture" aria-label="Permalink to &quot;2. Zero-trust architecture&quot;">​</a></h3><p>device posture (compliance + risk score) + JIT (just-in-time) access + micro-segmentation + continuous verification + policy enforcement point + never trust always verify.</p><h3 id="_3-siem-audit-log" tabindex="-1">3. SIEM + audit log <a class="header-anchor" href="#_3-siem-audit-log" aria-label="Permalink to &quot;3. SIEM + audit log&quot;">​</a></h3><p>structured logging + tamper-evident seal (chain hash + Merkle tree) + retention policy + correlation rule + alert routing + Splunk / ELK / Datadog compatibility.</p><h3 id="_4-incident-response" tabindex="-1">4. Incident response <a class="header-anchor" href="#_4-incident-response" aria-label="Permalink to &quot;4. Incident response&quot;">​</a></h3><p>playbook orchestrator + severity classification (P0-P4) + escalation ladder + forensics evidence collection + post-mortem template + timeline reconstruction + IR communication.</p><h3 id="_5-cryptography-advanced" tabindex="-1">5. Cryptography advanced <a class="header-anchor" href="#_5-cryptography-advanced" aria-label="Permalink to &quot;5. Cryptography advanced&quot;">​</a></h3><p>AEAD (AES-GCM + ChaCha20-Poly1305) + KDF (HKDF + PBKDF2 + Argon2) + envelope encryption (KEK + DEK) + key rotation + HSM (Hardware Security Module) + post-quantum ML-KEM (Kyber).</p><h3 id="_6-container-kubernetes-security" tabindex="-1">6. Container / Kubernetes security <a class="header-anchor" href="#_6-container-kubernetes-security" aria-label="Permalink to &quot;6. Container / Kubernetes security&quot;">​</a></h3><p>pod security policy + network policy + admission controller (OPA / Gatekeeper / Kyverno) + secrets management + rootless containers + read-only filesystem + service mesh mTLS.</p><h3 id="_7-supply-chain-security" tabindex="-1">7. Supply chain security <a class="header-anchor" href="#_7-supply-chain-security" aria-label="Permalink to &quot;7. Supply chain security&quot;">​</a></h3><p>SLSA level (v0.1 → L4) + reproducible build + signed provenance (Sigstore cosign) + attestation (in-toto) + SBOM verification + dependency pinning + supply chain policy.</p><h3 id="_8-web-vitals-security" tabindex="-1">8. Web Vitals security <a class="header-anchor" href="#_8-web-vitals-security" aria-label="Permalink to &quot;8. Web Vitals security&quot;">​</a></h3><p>subresource integrity (SRI) + trusted types + permissions policy + cross-origin isolation (COOP + COEP) + isolation-by-default + strict CSP integration + secure defaults.</p><h2 id="_3-dogfood-security-app-新規" tabindex="-1">3 dogfood security app 新規 <a class="header-anchor" href="#_3-dogfood-security-app-新規" aria-label="Permalink to &quot;3 dogfood security app 新規&quot;">​</a></h2><h3 id="dogfood-security-mtls-zero-trust-app-新規" tabindex="-1"><code>dogfood-security-mtls-zero-trust-app</code> 新規 <a class="header-anchor" href="#dogfood-security-mtls-zero-trust-app-新規" aria-label="Permalink to &quot;`dogfood-security-mtls-zero-trust-app` 新規&quot;">​</a></h3><p>mTLS handshake + SPKI pin + OCSP stapling + CT log + zero-trust posture + risk score + JIT + micro-segment walkthrough、 74 test.</p><h3 id="dogfood-security-siem-incident-app-新規" tabindex="-1"><code>dogfood-security-siem-incident-app</code> 新規 <a class="header-anchor" href="#dogfood-security-siem-incident-app-新規" aria-label="Permalink to &quot;`dogfood-security-siem-incident-app` 新規&quot;">​</a></h3><p>SIEM + audit log + tamper-evident seal + retention + correlation + IR playbook + severity + escalation + forensics + post-mortem + orchestrator walkthrough、 85 test.</p><h3 id="dogfood-security-supply-chain-slsa-app-新規" tabindex="-1"><code>dogfood-security-supply-chain-slsa-app</code> 新規 <a class="header-anchor" href="#dogfood-security-supply-chain-slsa-app-新規" aria-label="Permalink to &quot;`dogfood-security-supply-chain-slsa-app` 新規&quot;">​</a></h3><p>SLSA + reproducible build + signed provenance + attestation walkthrough、 76 test.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/security</span></span></code></pre></div><p>Migration guide (additive-only、 breaking change なし):</p><ul><li><a href="https://cardene777.github.io/kiwa/migrations/v1.38-to-v1.39" target="_blank" rel="noreferrer">v1.38 → v1.39 migration guide</a></li><li><a href="https://cardene777.github.io/kiwa/concepts/security-advanced-II-testing" target="_blank" rel="noreferrer">Security advanced II testing SSOT concept doc</a></li></ul>',34)])])}const y=a(s,[["render",n]]);export{h as __pageData,y as default};
